insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('ingles-a1', 'Inglés para conversar · Módulo 1: Lo esencial', 'Empieza de cero: saluda, preséntate, habla de tu rutina y de tu familia. Nivel A1.', 'El nivel A1 completo para quien empieza de cero, en lecciones de 5 minutos con juegos: escuchas, eliges, armas frases y escribes, con explicaciones de gramática en español. Al terminar puedes presentarte, hablar de tu rutina, comprar, pedir indicaciones y contar qué hiciste el fin de semana.', 'Principiante', 'Inglés', 59900, null, '', 'COP', 'ultra', 'Hello!', 'published', $nivela$[{"title":"Saludos y presentaciones","goal":"Saluda, preséntate y di de dónde eres.","color":"ultra","lessons":5},{"title":"Personas y familia","goal":"Usa el verbo to be, habla de tu familia y describe a otras personas.","color":"mango","lessons":6},{"title":"Números, hora y fechas","goal":"Cuenta hasta cien, di la hora, tu edad y los días de la semana.","color":"mint","lessons":7},{"title":"La casa y las cosas","goal":"Describe tu casa, di qué hay y nombra objetos del día a día.","color":"rose","lessons":4},{"title":"Mi rutina","goal":"Cuenta qué haces cada día con el presente simple.","color":"ultra","lessons":4},{"title":"Comida y compras","goal":"Pide comida, pregunta precios y di lo que te gusta.","color":"mango","lessons":6},{"title":"La ciudad","goal":"Nombra lugares, di dónde están y pide indicaciones.","color":"mint","lessons":4},{"title":"Gustos y habilidades","goal":"Habla de tus pasatiempos, de lo que sabes hacer y de cómo te sientes.","color":"rose","lessons":4},{"title":"Clima y ropa","goal":"Habla del clima, de la ropa y de lo que está pasando ahora.","color":"ultra","lessons":4},{"title":"El pasado","goal":"Cuenta dónde estuviste y qué hiciste el fin de semana.","color":"mango","lessons":3},{"title":"Examen final","goal":"Demuestra lo que aprendiste. Apruebas con 3 errores o menos y obtienes tu certificado.","color":"rose","lessons":1}]$nivela$::jsonb, 0)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('ingles-m2', 'Inglés para conversar · Módulo 2: El día a día', 'Conversaciones reales: restaurante, compras, teléfono, planes con amigos y el médico.', 'Practica las conversaciones que vas a tener de verdad: pedir en un restaurante, comprar y devolver, hablar por teléfono, hacer planes, explicar qué te duele y contar tu fin de semana. Cada lección trae un diálogo real y ejercicios para elegir qué responder.', 'Básico', 'Inglés', 59900, null, '', 'COP', 'mint', 'How are you?', 'published', $nivela$[{"title":"En la cafetería y el restaurante","goal":"Pide comida y bebida, haz una reserva y paga la cuenta.","color":"ultra","lessons":4},{"title":"De compras","goal":"Busca tu talla, pregunta por descuentos y haz una devolución.","color":"mango","lessons":4},{"title":"Teléfono y mensajes","goal":"Contesta llamadas, deja recados y escribe mensajes cortos.","color":"mint","lessons":4},{"title":"Planes con amigos","goal":"Invita, acepta o rechaza con amabilidad y queda en un lugar y hora.","color":"rose","lessons":4},{"title":"En el médico y la farmacia","goal":"Di qué te duele, explica tus síntomas y compra medicina.","color":"ultra","lessons":4},{"title":"Contar tu día","goal":"Cuenta qué hiciste y pregunta a otros por su fin de semana.","color":"mango","lessons":4},{"title":"Examen final","goal":"Apruebas con 3 errores o menos y obtienes tu certificado del módulo.","color":"rose","lessons":1}]$nivela$::jsonb, 1)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('ingles-m3', 'Inglés para conversar · Módulo 3: Viajar y trabajar', 'Aeropuerto, hotel, transporte, entrevista de trabajo, oficina y atención al cliente.', 'El inglés que necesitas para viajar sin estrés y para trabajar: check-in y migración, hotel, taxi y metro, entrevistas de trabajo, reuniones, correos y atención al cliente. Diálogos reales y ejercicios en cada lección.', 'Básico a intermedio', 'Inglés', 59900, null, '', 'COP', 'mango', 'Let''s go!', 'published', $nivela$[{"title":"En el aeropuerto","goal":"Haz el check-in, encuentra tu puerta y pasa migración.","color":"ultra","lessons":4},{"title":"En el hotel","goal":"Haz el check-in, pide lo que necesitas y pregunta qué visitar.","color":"mango","lessons":4},{"title":"Direcciones y transporte","goal":"Pregunta cómo llegar y muévete en taxi, metro y bus.","color":"mint","lessons":4},{"title":"Entrevista de trabajo","goal":"Preséntate, responde preguntas difíciles y cierra bien la entrevista.","color":"rose","lessons":4},{"title":"En la oficina","goal":"Habla en reuniones, pide informes y escribe correos de trabajo.","color":"ultra","lessons":4},{"title":"Atención al cliente","goal":"Atiende clientes, resuelve problemas y cierra ventas en inglés.","color":"mango","lessons":4},{"title":"Examen final","goal":"Apruebas con 3 errores o menos y obtienes tu certificado del módulo.","color":"rose","lessons":1}]$nivela$::jsonb, 2)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('reto-militar-hombres', 'Reto Militar 21 días · Hombres', 'Entrena como en un campamento militar desde tu casa, con sillas, botellas y una mochila.', '21 misiones diarias de 20 a 35 minutos, en tres semanas que suben de intensidad: Recluta, Soldado y Comando. Usas lo que ya tienes en casa: una silla, botellas de agua, una mochila con libros y una toalla. Cada ejercicio trae ilustración, técnica y consejos de seguridad. Haces una prueba el día 1 y otra el día 21 para medir tu avance.', 'Todos los niveles', 'Entrenamiento', 49900, null, '', 'COP', 'olive', 'MISIÓN 21', 'published', $nivela$[{"title":"Semana 1 · Recluta","goal":"Aprende la técnica y crea el hábito. Intensidad suave.","color":"olive","lessons":8},{"title":"Semana 2 · Soldado","goal":"Más rondas y menos descanso. Tu cuerpo ya se está adaptando.","color":"sand","lessons":7},{"title":"Semana 3 · Comando","goal":"La semana más exigente. Termina el reto y supera tu prueba inicial.","color":"ink","lessons":7}]$nivela$::jsonb, 3)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('reto-militar-mujeres', 'Reto Militar 21 días · Mujeres', 'Entrena como en un campamento militar desde tu casa, con más trabajo de piernas y glúteos.', '21 misiones diarias de 20 a 35 minutos, en tres semanas que suben de intensidad: Recluta, Soldado y Comando. Empieza con flexiones con rodillas apoyadas y da más trabajo a piernas y glúteos. Usas una silla, botellas de agua, una mochila y una toalla. Cada ejercicio trae ilustración, técnica y consejos de seguridad.', 'Todos los niveles', 'Entrenamiento', 49900, null, '', 'COP', 'sand', 'MISIÓN 21', 'published', $nivela$[{"title":"Semana 1 · Recluta","goal":"Aprende la técnica y crea el hábito. Intensidad suave.","color":"olive","lessons":8},{"title":"Semana 2 · Soldado","goal":"Más rondas y menos descanso. Tu cuerpo ya se está adaptando.","color":"sand","lessons":7},{"title":"Semana 3 · Comando","goal":"La semana más exigente. Termina el reto y supera tu prueba inicial.","color":"ink","lessons":7}]$nivela$::jsonb, 4)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('ventas-whatsapp', 'Domina las ventas por WhatsApp', 'De «¿precio?» a «ya te pagué»: guiones, objeciones y cierre para cualquier negocio.', 'Configura WhatsApp Business, responde rápido, pregunta antes de ofrecer, maneja el «está caro» y el «lo voy a pensar», cierra sin presionar y haz seguimiento sin molestar. Incluye plantillas listas para copiar y conversaciones de ejemplo.', 'Todos los niveles', 'Ventas', 69900, null, '', 'COP', 'mint', '¿Te lo separo?', 'published', $nivela$[{"title":"Prepara tu WhatsApp Business","goal":"Deja tu cuenta lista para vender: perfil, catálogo, etiquetas y mensajes automáticos.","color":"mint","lessons":3},{"title":"La conversación que vende","goal":"Responde rápido, pregunta antes de ofrecer y presenta beneficios, no solo características.","color":"ultra","lessons":3},{"title":"Manejo de objeciones","goal":"Responde con calma a «está caro», «lo voy a pensar» y «no confío».","color":"rose","lessons":3},{"title":"El cierre","goal":"Reconoce cuándo el cliente está listo y cierra la venta sin presionar.","color":"mango","lessons":3},{"title":"Después de la venta","goal":"Haz seguimiento sin molestar, consigue recomendaciones y vende productos digitales.","color":"ink","lessons":4}]$nivela$::jsonb, 5)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('ia-desde-cero', 'Inteligencia artificial desde cero', 'ChatGPT y Claude para escribir, vender, crear imágenes y editar videos.', 'Aprende a pedirle las cosas bien a la IA con la fórmula del buen prompt, y úsala para escribir, estudiar, organizarte, crear textos de venta, imágenes de producto, guiones y videos cortos. Incluye prompts listos para copiar.', 'Principiante', 'Tecnología', 79900, null, '', 'COP', 'ink', 'Prompt:', 'published', $nivela$[{"title":"Qué es la IA y cómo hablarle","goal":"Entiende qué puede hacer un asistente de IA y aprende a pedirle las cosas bien.","color":"ultra","lessons":3},{"title":"IA para tu día a día","goal":"Usa la IA para escribir, aprender y organizarte.","color":"mint","lessons":3},{"title":"IA para vender","goal":"Crea textos, respuestas y un mes de contenido con ayuda de la IA.","color":"mango","lessons":3},{"title":"Imágenes con IA","goal":"Crea y edita imágenes para tu negocio y tus redes.","color":"rose","lessons":3},{"title":"Video con IA","goal":"Escribe guiones, edita videos cortos y arma tu rutina semanal con IA.","color":"ink","lessons":3}]$nivela$::jsonb, 6)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;
insert into public.courses (slug, title, short, description, level, category, price, compare_at_price, badge, currency, color, cover, status, outline, sort) values ('redes-digitales', 'Vende productos digitales en redes', 'Crea tu negocio digital: cuenta que vende, contenido, pauta y programa de afiliados.', 'Desde elegir tu nicho y optimizar tu perfil hasta crear videos que retienen, armar tu calendario, lanzar tu primera campaña de pauta y medir resultados. Incluye cómo vender como afiliado de Nivela con honestidad.', 'Principiante', 'Negocios', 89900, null, '', 'COP', 'rose', '+1 venta', 'published', $nivela$[{"title":"Tu negocio digital desde casa","goal":"Entiende cómo se gana dinero con productos digitales, elige tu nicho y arranca en orden.","color":"mint","lessons":3},{"title":"Crea tu cuenta que vende","goal":"Optimiza tu perfil y aprende a crear contenido que la gente quiere ver.","color":"ultra","lessons":3},{"title":"Contenido que convierte","goal":"Planea tu mes, usa historias para vender y construye prueba social real.","color":"rose","lessons":3},{"title":"Pauta publicitaria","goal":"Lanza tu primera campaña con poco presupuesto y aprende a medirla.","color":"mango","lessons":3},{"title":"Vende como afiliado de Nivela","goal":"Usa tu enlace de afiliado para recomendar cursos y ganar comisiones con honestidad.","color":"ink","lessons":3}]$nivela$::jsonb, 7)
  on conflict (slug) do update set title = excluded.title, short = excluded.short, description = excluded.description, level = excluded.level, category = excluded.category, outline = excluded.outline, sort = excluded.sort;

