insert into public.bundles (slug, title, short, price, currency, color, cover, status, courses, sort) values ('kit-emprendedor', 'Kit emprendedor digital', 'Ventas por WhatsApp + Inteligencia artificial + Vende en redes. Todo para arrancar tu negocio.', 169900, 'COP', 'ink', 'Kit x3', 'published', array['ventas-whatsapp', 'ia-desde-cero', 'redes-digitales'], 1)
