insert into public.course_content (course_slug, data) values ('ingles-a1', $nivela${"id":"ingles-a1","certNote":"con nivel de referencia A1 del Marco Común Europeo","units":[{"id":"u1","title":"Saludos y presentaciones","goal":"Saluda, preséntate y di de dónde eres.","color":"ultra","lessons":[{"id":"u1-l1","title":"Hola y adiós","words":[["hello","hola"],["goodbye","adiós"],["good morning","buenos días"],["good afternoon","buenas tardes"],["good night","buenas noches"],["thank you","gracias"]],"sentences":[["Hello, good morning","Hola, buenos días"],["Thank you, goodbye","Gracias, adiós"],["Good night, thank you","Buenas noches, gracias"]]},{"id":"u1-l2","title":"Me presento","words":[["name","nombre"],["my","mi"],["your","tu"],["what","qué"],["is","es"],["nice to meet you","mucho gusto"]],"sentences":[["My name is Ana","Mi nombre es Ana"],["What is your name?","¿Cuál es tu nombre?"],["I am Carlos, nice to meet you","Soy Carlos, mucho gusto"]],"tip":{"title":"Presentarte","body":"Para decir tu nombre usa «My name is…» o «I am…». Las dos son correctas.","examples":[["My name is Laura","Mi nombre es Laura"],["I am Laura","Soy Laura"]]}},{"id":"u1-l3","title":"¿Cómo estás?","words":[["how","cómo"],["fine","bien"],["very","muy"],["and","y"],["tired","cansado"],["happy","feliz"]],"sentences":[["How are you?","¿Cómo estás?"],["I am fine, thank you","Estoy bien, gracias"],["I am very tired","Estoy muy cansado"]],"tip":{"title":"Ser y estar son lo mismo","body":"En inglés «ser» y «estar» son un solo verbo: to be. «I am» puede ser «soy» o «estoy». En conversación se acorta: I am → I'm.","examples":[["I am a student","Soy estudiante"],["I'm tired","Estoy cansado"]]}},{"id":"u1-l4","title":"¿De dónde eres?","words":[["where","dónde"],["from","de (origen)"],["country","país"],["city","ciudad"],["live","vivir"],["English","inglés"]],"sentences":[["Where are you from?","¿De dónde eres?"],["I am from Colombia","Soy de Colombia"],["I live in a big city","Vivo en una ciudad grande"]],"tip":{"title":"Países e idiomas","body":"En inglés los países, las ciudades y los idiomas siempre van con mayúscula.","examples":[["I am from Colombia","Soy de Colombia"],["I speak English","Hablo inglés"]]}},{"id":"u1-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u2","title":"Personas y familia","goal":"Usa el verbo to be, habla de tu familia y describe a otras personas.","color":"mango","lessons":[{"id":"u2-l1","title":"El verbo to be","words":[["I","yo"],["you","tú / usted"],["he","él"],["she","ella"],["we","nosotros"],["they","ellos"]],"sentences":[["She is a teacher","Ella es profesora"],["We are friends","Somos amigos"],["He is from Colombia","Él es de Colombia"]],"tip":{"title":"El verbo to be","body":"Cambia según la persona: I am, you are, he/she/it is, we are, they are.","examples":[["I am happy","Estoy feliz"],["She is happy","Ella está feliz"],["They are happy","Ellos están felices"]]}},{"id":"u2-l2","title":"La familia","words":[["mother","mamá"],["father","papá"],["brother","hermano"],["sister","hermana"],["son","hijo"],["daughter","hija"]],"sentences":[["This is my mother","Esta es mi mamá"],["I have a sister","Tengo una hermana"],["My father is a doctor","Mi papá es médico"]]},{"id":"u2-l3","title":"Profesiones","words":[["teacher","profesor"],["doctor","médico"],["student","estudiante"],["engineer","ingeniero"],["nurse","enfermero"],["lawyer","abogado"]],"sentences":[["I am a student","Soy estudiante"],["She is a nurse","Ella es enfermera"],["He is an engineer","Él es ingeniero"]],"tip":{"title":"A y an","body":"Con profesiones siempre va «a» o «an». Usa «an» si la palabra empieza con sonido de vocal.","examples":[["She is a nurse","Ella es enfermera"],["He is an engineer","Él es ingeniero"]]}},{"id":"u2-l4","title":"Describir personas","words":[["tall","alto"],["short","bajo"],["young","joven"],["beautiful","hermoso"],["friendly","amable"],["funny","divertido"]],"sentences":[["My sister is tall","Mi hermana es alta"],["He is very friendly","Él es muy amable"],["They are young","Ellos son jóvenes"]],"tip":{"title":"Los adjetivos no cambian","body":"En inglés el adjetivo no tiene femenino ni plural, y va antes del sustantivo.","examples":[["a tall man","un hombre alto"],["two tall women","dos mujeres altas"]]}},{"id":"u2-l5","title":"Su, nuestro, sus","words":[["his","su (de él)"],["her","su (de ella)"],["our","nuestro"],["their","su (de ellos)"],["husband","esposo"],["wife","esposa"]],"sentences":[["Her husband is a doctor","Su esposo es médico"],["This is our house","Esta es nuestra casa"],["His wife is from Peru","Su esposa es de Perú"]],"tip":{"title":"Posesivos","body":"El español dice «su» para todo, pero en inglés depende de quién es el dueño: his (de él), her (de ella), their (de ellos).","examples":[["his car","su carro (de él)"],["her car","su carro (de ella)"],["our car","nuestro carro"]]}},{"id":"u2-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u3","title":"Números, hora y fechas","goal":"Cuenta hasta cien, di la hora, tu edad y los días de la semana.","color":"mint","lessons":[{"id":"u3-l1","title":"Números del 1 al 10","words":[["one","uno"],["two","dos"],["three","tres"],["five","cinco"],["seven","siete"],["ten","diez"]],"sentences":[["I have two brothers","Tengo dos hermanos"],["Ten students","Diez estudiantes"],["She has three sons","Ella tiene tres hijos"]]},{"id":"u3-l2","title":"Colores","words":[["red","rojo"],["blue","azul"],["green","verde"],["yellow","amarillo"],["black","negro"],["white","blanco"]],"sentences":[["The car is red","El carro es rojo"],["The house is white","La casa es blanca"],["My favorite color is blue","Mi color favorito es el azul"]]},{"id":"u3-l3","title":"¿Cuántos años tienes?","words":[["years","años"],["old","viejo"],["twenty","veinte"],["thirty","treinta"],["birthday","cumpleaños"],["today","hoy"]],"sentences":[["How old are you?","¿Cuántos años tienes?"],["I am twenty years old","Tengo veinte años"],["My birthday is today","Mi cumpleaños es hoy"]],"tip":{"title":"La edad se dice con to be","body":"En español «tienes» años, pero en inglés «eres» años: se usa el verbo to be.","examples":[["I am thirty years old","Tengo treinta años"],["How old is she?","¿Cuántos años tiene ella?"]]}},{"id":"u3-l4","title":"Más números","words":[["eleven","once"],["twelve","doce"],["fifteen","quince"],["forty","cuarenta"],["fifty","cincuenta"],["one hundred","cien"]],"sentences":[["I am forty years old","Tengo cuarenta años"],["It costs fifty dollars","Cuesta cincuenta dólares"],["There are twelve months","Hay doce meses"]]},{"id":"u3-l5","title":"¿Qué hora es?","words":[["time","hora"],["o'clock","en punto"],["half past","y media"],["morning","mañana"],["night","noche"],["minute","minuto"]],"sentences":[["What time is it?","¿Qué hora es?"],["It is three o'clock","Son las tres en punto"],["It is half past seven","Son las siete y media"]],"tip":{"title":"Decir la hora","body":"Para la hora exacta: «It is» + número + «o'clock». Para y media: «half past» + la hora.","examples":[["It is five o'clock","Son las cinco"],["It is half past five","Son las cinco y media"]]}},{"id":"u3-l6","title":"Días y meses","words":[["Monday","lunes"],["Friday","viernes"],["Sunday","domingo"],["week","semana"],["month","mes"],["January","enero"]],"sentences":[["Today is Monday","Hoy es lunes"],["My birthday is in January","Mi cumpleaños es en enero"],["I work from Monday to Friday","Trabajo de lunes a viernes"]],"tip":{"title":"Mayúsculas","body":"En inglés los días y los meses siempre van con mayúscula. Con días se usa «on» y con meses «in».","examples":[["on Monday","el lunes"],["in January","en enero"]]}},{"id":"u3-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u4","title":"La casa y las cosas","goal":"Describe tu casa, di qué hay y nombra objetos del día a día.","color":"rose","lessons":[{"id":"u4-l1","title":"Mi casa","words":[["house","casa"],["kitchen","cocina"],["bedroom","habitación"],["bathroom","baño"],["door","puerta"],["window","ventana"]],"sentences":[["The kitchen is big","La cocina es grande"],["My bedroom is small","Mi habitación es pequeña"],["The door is open","La puerta está abierta"]]},{"id":"u4-l2","title":"Hay","words":[["table","mesa"],["chair","silla"],["bed","cama"],["sofa","sofá"],["lamp","lámpara"],["garden","jardín"]],"sentences":[["There is a table in the kitchen","Hay una mesa en la cocina"],["There are two chairs","Hay dos sillas"],["Is there a garden?","¿Hay un jardín?"]],"tip":{"title":"There is y there are","body":"«Hay» se dice «there is» con una cosa y «there are» con varias.","examples":[["There is a bed","Hay una cama"],["There are three beds","Hay tres camas"]]}},{"id":"u4-l3","title":"Objetos y plurales","words":[["phone","celular"],["book","libro"],["key","llave"],["bag","bolso"],["computer","computador"],["pen","bolígrafo"]],"sentences":[["This is my phone","Este es mi celular"],["These are my keys","Estas son mis llaves"],["The books are on the table","Los libros están en la mesa"]],"tip":{"title":"This y these","body":"El plural casi siempre se forma con -s. «This» es para una cosa cercana y «these» para varias.","examples":[["this book","este libro"],["these books","estos libros"]]}},{"id":"u4-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u5","title":"Mi rutina","goal":"Cuenta qué haces cada día con el presente simple.","color":"ultra","lessons":[{"id":"u5-l1","title":"Mi día","words":[["wake up","despertarse"],["work","trabajar"],["sleep","dormir"],["study","estudiar"],["go","ir"],["eat","comer"]],"sentences":[["I wake up at six","Me despierto a las seis"],["I work in an office","Trabajo en una oficina"],["We study English at night","Estudiamos inglés en la noche"]],"tip":{"title":"Presente simple","body":"Para hábitos y rutinas el verbo va sin cambios con I, you, we y they.","examples":[["I work","Yo trabajo"],["They work","Ellos trabajan"]]}},{"id":"u5-l2","title":"Él y ella","words":[["cook","cocinar"],["read","leer"],["play","jugar"],["watch","mirar"],["drive","manejar"],["walk","caminar"]],"sentences":[["She cooks every day","Ella cocina todos los días"],["He reads the newspaper","Él lee el periódico"],["My son plays soccer","Mi hijo juega fútbol"]],"tip":{"title":"La -s de he, she, it","body":"Con he, she e it el verbo lleva -s al final. Es el error más común en inglés.","examples":[["I cook","Yo cocino"],["She cooks","Ella cocina"]]}},{"id":"u5-l3","title":"Preguntas y negaciones","words":[["always","siempre"],["never","nunca"],["sometimes","a veces"],["usually","normalmente"],["early","temprano"],["late","tarde (con retraso)"]],"sentences":[["Do you work on Saturday?","¿Trabajas el sábado?"],["I don't drink coffee","No tomo café"],["She never eats meat","Ella nunca come carne"]],"tip":{"title":"Do y does","body":"Para preguntar se pone «do» antes (o «does» con he/she). Para negar: «don't» o «doesn't».","examples":[["Do you cook?","¿Cocinas?"],["He doesn't cook","Él no cocina"]]}},{"id":"u5-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u6","title":"Comida y compras","goal":"Pide comida, pregunta precios y di lo que te gusta.","color":"mango","lessons":[{"id":"u6-l1","title":"En la mesa","words":[["bread","pan"],["rice","arroz"],["chicken","pollo"],["egg","huevo"],["fruit","fruta"],["cheese","queso"]],"sentences":[["I eat rice and chicken","Como arroz y pollo"],["The bread is good","El pan es bueno"],["I want an egg","Quiero un huevo"]]},{"id":"u6-l2","title":"Bebidas","words":[["water","agua"],["coffee","café"],["milk","leche"],["juice","jugo"],["tea","té"],["please","por favor"]],"sentences":[["I drink coffee","Tomo café"],["A glass of water, please","Un vaso de agua, por favor"],["She drinks tea","Ella toma té"]]},{"id":"u6-l3","title":"Me gusta","words":[["like","gustar"],["want","querer"],["delicious","delicioso"],["breakfast","desayuno"],["lunch","almuerzo"],["dinner","cena"]],"sentences":[["I like coffee","Me gusta el café"],["I don't like milk","No me gusta la leche"],["Breakfast is delicious","El desayuno está delicioso"]],"tip":{"title":"Me gusta = I like","body":"En inglés la persona va primero: «I like» (a mí me gusta). Para negar: «I don't like».","examples":[["I like fruit","Me gusta la fruta"],["She doesn't like tea","A ella no le gusta el té"]]}},{"id":"u6-l4","title":"En la tienda","words":[["how much","cuánto"],["price","precio"],["cheap","barato"],["expensive","caro"],["money","dinero"],["buy","comprar"]],"sentences":[["How much is the bread?","¿Cuánto cuesta el pan?"],["It is very expensive","Es muy caro"],["I want to buy fruit","Quiero comprar fruta"]],"tip":{"title":"Preguntar el precio","body":"«How much is…?» para una cosa y «How much are…?» para varias.","examples":[["How much is this?","¿Cuánto cuesta esto?"],["How much are the eggs?","¿Cuánto cuestan los huevos?"]]}},{"id":"u6-l5","title":"En el restaurante","words":[["menu","menú"],["bill","cuenta"],["waiter","mesero"],["fish","pescado"],["soup","sopa"],["order","pedir"]],"sentences":[["Can I have the menu, please?","¿Me trae el menú, por favor?"],["The bill, please","La cuenta, por favor"],["I would like the fish","Quisiera el pescado"]],"tip":{"title":"Pedir con amabilidad","body":"«I would like» (quisiera) es más amable que «I want» (quiero). Úsalo en restaurantes y tiendas.","examples":[["I would like a coffee","Quisiera un café"],["I'd like the soup","Quisiera la sopa"]]}},{"id":"u6-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u7","title":"La ciudad","goal":"Nombra lugares, di dónde están y pide indicaciones.","color":"mint","lessons":[{"id":"u7-l1","title":"Lugares","words":[["bank","banco"],["hospital","hospital"],["school","colegio"],["supermarket","supermercado"],["park","parque"],["church","iglesia"]],"sentences":[["Where is the hospital?","¿Dónde está el hospital?"],["The bank is near the park","El banco está cerca del parque"],["My son goes to school","Mi hijo va al colegio"]]},{"id":"u7-l2","title":"¿Dónde está?","words":[["next to","al lado de"],["in front of","frente a"],["behind","detrás de"],["near","cerca de"],["between","entre"],["street","calle"]],"sentences":[["The store is next to the bank","La tienda está al lado del banco"],["The park is behind the church","El parque está detrás de la iglesia"],["I live on this street","Vivo en esta calle"]],"tip":{"title":"Preposiciones de lugar","body":"Para decir dónde está algo usa «is» + la preposición + el lugar.","examples":[["The bank is near the park","El banco está cerca del parque"],["The car is in front of the house","El carro está frente a la casa"]]}},{"id":"u7-l3","title":"Transporte e indicaciones","words":[["bus","bus"],["taxi","taxi"],["car","carro"],["turn left","gira a la izquierda"],["turn right","gira a la derecha"],["straight","derecho"]],"sentences":[["I go to work by bus","Voy al trabajo en bus"],["Turn left at the bank","Gira a la izquierda en el banco"],["Go straight","Sigue derecho"]],"tip":{"title":"By bus, by car","body":"Para decir en qué te transportas usa «by»: by bus, by car, by taxi. Caminando es «on foot».","examples":[["I go by car","Voy en carro"],["She goes on foot","Ella va a pie"]]}},{"id":"u7-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u8","title":"Gustos y habilidades","goal":"Habla de tus pasatiempos, de lo que sabes hacer y de cómo te sientes.","color":"rose","lessons":[{"id":"u8-l1","title":"Pasatiempos","words":[["music","música"],["movies","películas"],["dance","bailar"],["sing","cantar"],["swim","nadar"],["soccer","fútbol"]],"sentences":[["I like music","Me gusta la música"],["She loves movies","A ella le encantan las películas"],["We play soccer on Sunday","Jugamos fútbol el domingo"]]},{"id":"u8-l2","title":"Puedo, no puedo","words":[["can","poder"],["guitar","guitarra"],["piano","piano"],["ride","montar"],["bike","bicicleta"],["speak","hablar"]],"sentences":[["I can swim","Sé nadar"],["She can't drive","Ella no sabe manejar"],["Can you speak English?","¿Sabes hablar inglés?"]],"tip":{"title":"Can y can't","body":"«Can» sirve para poder y saber hacer algo. No cambia con ninguna persona y el verbo va sin «to».","examples":[["He can dance","Él sabe bailar"],["I can't swim","No sé nadar"]]}},{"id":"u8-l3","title":"¿Cómo te sientes?","words":[["hungry","hambriento"],["thirsty","sediento"],["sad","triste"],["angry","enojado"],["bored","aburrido"],["sick","enfermo"]],"sentences":[["I am hungry","Tengo hambre"],["Are you sad?","¿Estás triste?"],["The children are bored","Los niños están aburridos"]],"tip":{"title":"Tengo hambre = I am hungry","body":"El hambre, la sed y el frío se dicen con to be, no con «have».","examples":[["I am thirsty","Tengo sed"],["I am cold","Tengo frío"]]}},{"id":"u8-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u9","title":"Clima y ropa","goal":"Habla del clima, de la ropa y de lo que está pasando ahora.","color":"ultra","lessons":[{"id":"u9-l1","title":"El clima","words":[["weather","clima"],["sunny","soleado"],["rain","lluvia"],["cold","frío"],["hot","caluroso"],["cloudy","nublado"]],"sentences":[["It is sunny today","Hoy está soleado"],["It is very cold","Hace mucho frío"],["How is the weather?","¿Cómo está el clima?"]],"tip":{"title":"It is…","body":"Para hablar del clima siempre se empieza con «It is» (o «It's»).","examples":[["It's hot","Hace calor"],["It's cloudy","Está nublado"]]}},{"id":"u9-l2","title":"La ropa","words":[["shirt","camisa"],["pants","pantalón"],["shoes","zapatos"],["dress","vestido"],["jacket","chaqueta"],["hat","sombrero"]],"sentences":[["I need new shoes","Necesito zapatos nuevos"],["Her dress is green","Su vestido es verde"],["This jacket is cheap","Esta chaqueta es barata"]]},{"id":"u9-l3","title":"¿Qué estás haciendo?","words":[["wear","llevar puesto"],["now","ahora"],["wait","esperar"],["listen","escuchar"],["write","escribir"],["open","abrir"]],"sentences":[["What are you doing?","¿Qué estás haciendo?"],["She is cooking now","Ella está cocinando ahora"],["It is raining","Está lloviendo"]],"tip":{"title":"Presente continuo","body":"Para lo que pasa en este momento: to be + verbo con -ing.","examples":[["I am working","Estoy trabajando"],["They are eating","Están comiendo"]]}},{"id":"u9-repaso","title":"Repaso de la unidad","review":true}]},{"id":"u10","title":"El pasado","goal":"Cuenta dónde estuviste y qué hiciste el fin de semana.","color":"mango","lessons":[{"id":"u10-l1","title":"Was y were","words":[["yesterday","ayer"],["weekend","fin de semana"],["last night","anoche"],["party","fiesta"],["at home","en casa"],["ago","hace (tiempo)"]],"sentences":[["I was at home yesterday","Ayer estuve en casa"],["We were at a party","Estuvimos en una fiesta"],["Where were you last night?","¿Dónde estabas anoche?"]],"tip":{"title":"El pasado de to be","body":"«Was» con I, he, she, it. «Were» con you, we, they.","examples":[["I was tired","Estaba cansado"],["They were at home","Estaban en casa"]]}},{"id":"u10-l2","title":"Mi fin de semana","words":[["visited","visitó"],["watched","vio"],["cooked","cocinó"],["called","llamó"],["worked","trabajó"],["stayed","se quedó"]],"sentences":[["I visited my mother","Visité a mi mamá"],["We watched a movie","Vimos una película"],["She called me yesterday","Ella me llamó ayer"]],"tip":{"title":"Pasado con -ed","body":"Muchos verbos forman el pasado agregando -ed, y es igual para todas las personas.","examples":[["I worked","Trabajé"],["She worked","Ella trabajó"]]}},{"id":"u10-repaso","title":"Repaso de la unidad","review":true}]},{"id":"final","title":"Examen final","goal":"Demuestra lo que aprendiste. Apruebas con 3 errores o menos y obtienes tu certificado.","color":"rose","lessons":[{"id":"examen-final","title":"Examen final A1","exam":true}]}]}$nivela$::jsonb)
  on conflict (course_slug) do update set data = excluded.data;
insert into public.course_content (course_slug, data) values ('ingles-m2', $nivela${"id":"ingles-m2","units":[{"id":"m2u1","title":"En la cafetería y el restaurante","goal":"Pide comida y bebida, haz una reserva y paga la cuenta.","color":"ultra","lessons":[{"id":"m2u1-l1","title":"Pedir en la cafetería","words":[["cup","taza"],["small","pequeño"],["large","grande"],["to go","para llevar"],["sugar","azúcar"],["cash","efectivo"]],"sentences":[["A large coffee to go, please","Un café grande para llevar, por favor"],["Do you have sugar?","¿Tiene azúcar?"],["Can I pay in cash?","¿Puedo pagar en efectivo?"]],"dialogue":[["A","Hi! What can I get you?","¡Hola! ¿Qué te sirvo?"],["B","A small coffee, please.","Un café pequeño, por favor."],["A","For here or to go?","¿Para tomar aquí o para llevar?"],["B","To go, thanks.","Para llevar, gracias."]],"tip":{"title":"Pedir con amabilidad","body":"Para pedir algo usa «Can I have…?» o, más formal, «Could I have…?». Al final agrega «please».","examples":[["Can I have a coffee, please?","¿Me da un café, por favor?"],["Could I have some water?","¿Me podría dar agua?"]]}},{"id":"m2u1-l2","title":"En el restaurante","words":[["reservation","reserva"],["starter","plato de entrada"],["dessert","postre"],["spicy","picante"],["vegetarian","vegetariano"],["tip","propina"]],"sentences":[["I have a reservation for two","Tengo una reserva para dos"],["Is the soup spicy?","¿La sopa es picante?"],["We would like dessert","Quisiéramos postre"]],"dialogue":[["A","Are you ready to order?","¿Están listos para pedir?"],["B","Yes, I'd like the chicken, please.","Sí, quisiera el pollo, por favor."],["A","Anything to drink?","¿Algo de tomar?"],["B","Just water, thanks.","Solo agua, gracias."]]},{"id":"m2u1-l3","title":"Pagar la cuenta","words":[["wrong","equivocado"],["cold","frío"],["change","cambio (vuelto)"],["receipt","recibo"],["card","tarjeta"],["sorry","perdón"]],"sentences":[["Sorry, this is not my order","Perdón, este no es mi pedido"],["The food is cold","La comida está fría"],["Can I pay by card?","¿Puedo pagar con tarjeta?"]],"dialogue":[["B","Excuse me, can we have the bill?","Disculpe, ¿nos trae la cuenta?"],["A","Of course. Cash or card?","Claro. ¿Efectivo o tarjeta?"],["B","Card, please.","Tarjeta, por favor."],["A","Here is your receipt.","Aquí está su recibo."]]},{"id":"m2u1-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2u2","title":"De compras","goal":"Busca tu talla, pregunta por descuentos y haz una devolución.","color":"mango","lessons":[{"id":"m2u2-l1","title":"En la tienda de ropa","words":[["size","talla"],["fitting room","probador"],["try on","probarse"],["smaller","más pequeño"],["bigger","más grande"],["look for","buscar"]],"sentences":[["Can I try it on?","¿Me lo puedo probar?"],["Do you have a smaller size?","¿Tiene una talla más pequeña?"],["I am looking for a jacket","Estoy buscando una chaqueta"]],"dialogue":[["A","Can I help you?","¿Le puedo ayudar?"],["B","Yes, I'm looking for a shirt.","Sí, estoy buscando una camisa."],["A","What size are you?","¿Qué talla usa?"],["B","Medium, please.","Mediana, por favor."]],"tip":{"title":"Comparar: -er","body":"Para decir «más…» con palabras cortas agrega -er: small → smaller, big → bigger.","examples":[["a bigger size","una talla más grande"],["This one is cheaper","Este es más barato"]]}},{"id":"m2u2-l2","title":"Precios y descuentos","words":[["discount","descuento"],["sale","rebaja"],["total","total"],["only","solo"],["each","cada uno"],["free","gratis"]],"sentences":[["Is this on sale?","¿Esto está en rebaja?"],["They are ten dollars each","Cuestan diez dólares cada uno"],["The second one is free","El segundo es gratis"]],"dialogue":[["B","How much is this bag?","¿Cuánto cuesta este bolso?"],["A","It's forty dollars.","Cuesta cuarenta dólares."],["B","Is there a discount?","¿Hay algún descuento?"],["A","Yes, twenty percent off today.","Sí, veinte por ciento menos hoy."]]},{"id":"m2u2-l3","title":"Devoluciones","words":[["return","devolver"],["broken","roto"],["exchange","cambiar"],["refund","reembolso"],["manager","gerente"],["problem","problema"]],"sentences":[["I want to return these shoes","Quiero devolver estos zapatos"],["This cup is broken","Esta taza está rota"],["Can I speak to the manager?","¿Puedo hablar con el gerente?"]],"dialogue":[["B","Hi, I'd like to return this.","Hola, quisiera devolver esto."],["A","What's the problem?","¿Cuál es el problema?"],["B","It doesn't work.","No funciona."],["A","Do you want a refund or an exchange?","¿Quiere un reembolso o un cambio?"]]},{"id":"m2u2-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2u3","title":"Teléfono y mensajes","goal":"Contesta llamadas, deja recados y escribe mensajes cortos.","color":"mint","lessons":[{"id":"m2u3-l1","title":"Contestar el teléfono","words":[["call back","devolver la llamada"],["hold on","espere un momento"],["speak up","hable más fuerte"],["message","mensaje"],["busy","ocupado"],["number","número"]],"sentences":[["Can you call me back later?","¿Me puedes devolver la llamada más tarde?"],["Hold on, please","Espere un momento, por favor"],["Sorry, he is busy now","Lo siento, él está ocupado ahora"]],"dialogue":[["A","Hello, this is Laura.","Hola, habla Laura."],["B","Hi Laura, is Mark there?","Hola Laura, ¿está Mark?"],["A","Sorry, he's busy. Can I take a message?","Lo siento, está ocupado. ¿Le dejo un mensaje?"],["B","Yes, please ask him to call me back.","Sí, por favor dile que me devuelva la llamada."]],"tip":{"title":"Al teléfono","body":"Para decir quién eres al teléfono se usa «This is…», no «I am…».","examples":[["Hello, this is Laura","Hola, habla Laura"],["Is Mark there?","¿Está Mark?"]]}},{"id":"m2u3-l2","title":"Mensajes de texto","words":[["text","escribir un mensaje"],["on my way","voy en camino"],["running late","voy retrasado"],["see you soon","nos vemos pronto"],["sure","claro"],["no problem","no hay problema"]],"sentences":[["I'm on my way","Voy en camino"],["Sorry, I'm running late","Perdón, voy retrasado"],["Text me when you arrive","Escríbeme cuando llegues"]],"dialogue":[["A","Where are you?","¿Dónde estás?"],["B","I'm on my way. I'm running late.","Voy en camino. Voy retrasado."],["A","No problem. See you soon.","No hay problema. Nos vemos pronto."],["B","Thanks! Ten minutes.","¡Gracias! Diez minutos."]]},{"id":"m2u3-l3","title":"Deletrear y repetir","words":[["spell","deletrear"],["email","correo electrónico"],["address","dirección"],["repeat","repetir"],["slowly","despacio"],["again","otra vez"]],"sentences":[["Can you spell your name?","¿Puedes deletrear tu nombre?"],["Could you repeat that, please?","¿Podrías repetir eso, por favor?"],["Please speak slowly","Por favor habla despacio"]],"dialogue":[["A","What's your email address?","¿Cuál es tu correo electrónico?"],["B","It's ana at gmail dot com.","Es ana arroba gmail punto com."],["A","Sorry, can you say that again?","Perdón, ¿lo puedes decir otra vez?"],["B","Sure: A-N-A at gmail dot com.","Claro: A-N-A arroba gmail punto com."]],"tip":{"title":"Arroba y punto","body":"En un correo, @ se dice «at» y el punto se dice «dot».","examples":[["ana at gmail dot com","ana@gmail.com"],["Can you spell it?","¿Lo puedes deletrear?"]]}},{"id":"m2u3-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2u4","title":"Planes con amigos","goal":"Invita, acepta o rechaza con amabilidad y queda en un lugar y hora.","color":"rose","lessons":[{"id":"m2u4-l1","title":"Invitar","words":[["invite","invitar"],["tonight","esta noche"],["tomorrow","mañana"],["available","disponible"],["together","juntos"],["plan","plan"]],"sentences":[["Do you want to go to the movies?","¿Quieres ir a cine?"],["Let's go together","Vamos juntos"],["Are you available tomorrow?","¿Estás disponible mañana?"]],"dialogue":[["A","Do you have plans tonight?","¿Tienes planes esta noche?"],["B","No, why?","No, ¿por qué?"],["A","Let's go out for dinner.","Salgamos a cenar."],["B","Great idea!","¡Buena idea!"]],"tip":{"title":"Let's…","body":"«Let's» + verbo sirve para proponer un plan: es como decir «vamos a…».","examples":[["Let's eat","Comamos"],["Let's go to the beach","Vamos a la playa"]]}},{"id":"m2u4-l2","title":"Aceptar y rechazar","words":[["of course","por supuesto"],["maybe","tal vez"],["next time","la próxima vez"],["can't","no puedo"],["would love to","me encantaría"],["another day","otro día"]],"sentences":[["I would love to","Me encantaría"],["Sorry, I can't tonight","Lo siento, no puedo esta noche"],["Maybe next time","Tal vez la próxima vez"]],"dialogue":[["A","Do you want to come to my party?","¿Quieres venir a mi fiesta?"],["B","When is it?","¿Cuándo es?"],["A","On Saturday at eight.","El sábado a las ocho."],["B","I'd love to! Thanks.","¡Me encantaría! Gracias."]]},{"id":"m2u4-l3","title":"Lugar y hora","words":[["meet","encontrarse"],["place","lugar"],["early","temprano"],["later","más tarde"],["corner","esquina"],["entrance","entrada"]],"sentences":[["Let's meet at the entrance","Encontrémonos en la entrada"],["What time is good for you?","¿A qué hora te queda bien?"],["See you at the corner","Nos vemos en la esquina"]],"dialogue":[["A","Where do we meet?","¿Dónde nos encontramos?"],["B","In front of the cinema.","Frente al cine."],["A","What time?","¿A qué hora?"],["B","At seven. Don't be late!","A las siete. ¡No llegues tarde!"]]},{"id":"m2u4-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2u5","title":"En el médico y la farmacia","goal":"Di qué te duele, explica tus síntomas y compra medicina.","color":"ultra","lessons":[{"id":"m2u5-l1","title":"¿Qué te duele?","words":[["head","cabeza"],["stomach","estómago"],["back","espalda"],["throat","garganta"],["hand","mano"],["leg","pierna"]],"sentences":[["My head hurts","Me duele la cabeza"],["I have a sore throat","Tengo dolor de garganta"],["My back hurts","Me duele la espalda"]],"dialogue":[["A","What's wrong?","¿Qué te pasa?"],["B","My stomach hurts.","Me duele el estómago."],["A","Since when?","¿Desde cuándo?"],["B","Since yesterday.","Desde ayer."]],"tip":{"title":"Me duele = …hurts","body":"En inglés lo que duele va primero, con «my»: «My head hurts» (me duele la cabeza).","examples":[["My leg hurts","Me duele la pierna"],["My hands hurt","Me duelen las manos"]]}},{"id":"m2u5-l2","title":"En el médico","words":[["appointment","cita"],["fever","fiebre"],["cough","tos"],["headache","dolor de cabeza"],["medicine","medicina"],["rest","descansar"]],"sentences":[["I need an appointment","Necesito una cita"],["I have a fever and a cough","Tengo fiebre y tos"],["You need to rest","Necesitas descansar"]],"dialogue":[["A","How can I help you?","¿En qué le puedo ayudar?"],["B","I have a fever.","Tengo fiebre."],["A","Take this medicine twice a day.","Tome esta medicina dos veces al día."],["B","Thank you, doctor.","Gracias, doctor."]]},{"id":"m2u5-l3","title":"En la farmacia","words":[["pharmacy","farmacia"],["pills","pastillas"],["allergic","alérgico"],["prescription","receta"],["twice a day","dos veces al día"],["after meals","después de comer"]],"sentences":[["Do I need a prescription?","¿Necesito receta?"],["I am allergic to penicillin","Soy alérgico a la penicilina"],["Take two pills after meals","Tome dos pastillas después de comer"]],"dialogue":[["A","Good afternoon. What do you need?","Buenas tardes. ¿Qué necesita?"],["B","Something for a headache.","Algo para el dolor de cabeza."],["A","Are you allergic to anything?","¿Es alérgico a algo?"],["B","No, I'm not.","No, no lo soy."]]},{"id":"m2u5-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2u6","title":"Contar tu día","goal":"Cuenta qué hiciste y pregunta a otros por su fin de semana.","color":"mango","lessons":[{"id":"m2u6-l1","title":"Verbos irregulares","words":[["went","fue (ir)"],["had","tuvo"],["saw","vio"],["ate","comió"],["got up","se levantó"],["came","vino"]],"sentences":[["I went to the beach","Fui a la playa"],["We had a great time","La pasamos muy bien"],["She saw a movie","Ella vio una película"]],"dialogue":[["A","What did you do yesterday?","¿Qué hiciste ayer?"],["B","I got up late and went to the park.","Me levanté tarde y fui al parque."],["A","Nice! Did you eat there?","¡Qué bien! ¿Comiste allá?"],["B","Yes, I ate a sandwich.","Sí, me comí un sándwich."]],"tip":{"title":"Pasados irregulares","body":"Algunos verbos muy usados no llevan -ed: go → went, have → had, see → saw, eat → ate.","examples":[["I went home","Fui a casa"],["She had lunch","Ella almorzó"]]}},{"id":"m2u6-l2","title":"¿Cómo estuvo?","words":[["how was","cómo estuvo"],["fun","divertido"],["boring","aburrido"],["amazing","increíble"],["weekend","fin de semana"],["trip","viaje"]],"sentences":[["How was your weekend?","¿Cómo estuvo tu fin de semana?"],["It was amazing","Fue increíble"],["The trip was boring","El viaje fue aburrido"]],"dialogue":[["A","How was your trip?","¿Cómo estuvo tu viaje?"],["B","It was great. I went to the beach.","Estuvo genial. Fui a la playa."],["A","Lucky you!","¡Qué suerte!"],["B","What about you?","¿Y tú?"]]},{"id":"m2u6-l3","title":"¿Lo hiciste?","words":[["last week","la semana pasada"],["already","ya"],["yet","todavía"],["finish","terminar"],["start","empezar"],["forget","olvidar"]],"sentences":[["Did you finish the report?","¿Terminaste el informe?"],["I didn't forget","No se me olvidó"],["We started last week","Empezamos la semana pasada"]],"dialogue":[["A","Did you call your mom?","¿Llamaste a tu mamá?"],["B","Yes, I called her this morning.","Sí, la llamé esta mañana."],["A","Did she like the gift?","¿Le gustó el regalo?"],["B","She loved it!","¡Le encantó!"]],"tip":{"title":"Did y didn't","body":"Para preguntar en pasado: «Did» + verbo normal. Para negar: «didn't» + verbo normal (sin -ed).","examples":[["Did you go?","¿Fuiste?"],["I didn't go","No fui"]]}},{"id":"m2u6-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m2final","title":"Examen final","goal":"Apruebas con 3 errores o menos y obtienes tu certificado del módulo.","color":"rose","lessons":[{"id":"m2-examen","title":"Examen del módulo 2","exam":true}]}]}$nivela$::jsonb)
  on conflict (course_slug) do update set data = excluded.data;
insert into public.course_content (course_slug, data) values ('ingles-m3', $nivela${"id":"ingles-m3","units":[{"id":"m3u1","title":"En el aeropuerto","goal":"Haz el check-in, encuentra tu puerta y pasa migración.","color":"ultra","lessons":[{"id":"m3u1-l1","title":"Check-in","words":[["passport","pasaporte"],["flight","vuelo"],["luggage","equipaje"],["boarding pass","pase de abordar"],["window seat","puesto de ventana"],["aisle seat","puesto de pasillo"]],"sentences":[["Here is my passport","Aquí está mi pasaporte"],["Can I have a window seat?","¿Me da un puesto de ventana?"],["I have one bag to check","Tengo una maleta para documentar"]],"dialogue":[["A","Good morning. Passport, please.","Buenos días. Pasaporte, por favor."],["B","Here you are.","Aquí tiene."],["A","Any bags to check?","¿Alguna maleta para documentar?"],["B","Just one.","Solo una."]]},{"id":"m3u1-l2","title":"Puerta y abordaje","words":[["gate","puerta de embarque"],["delayed","retrasado"],["on time","a tiempo"],["boarding","abordaje"],["departure","salida"],["arrival","llegada"]],"sentences":[["Where is gate twelve?","¿Dónde está la puerta doce?"],["My flight is delayed","Mi vuelo está retrasado"],["Boarding starts at nine","El abordaje empieza a las nueve"]],"dialogue":[["A","Excuse me, is this flight on time?","Disculpe, ¿este vuelo sale a tiempo?"],["B","No, it's delayed one hour.","No, tiene una hora de retraso."],["A","Oh no! Thanks.","¡Ay no! Gracias."],["B","You're welcome.","Con gusto."]]},{"id":"m3u1-l3","title":"Migración","words":[["purpose","propósito"],["business","negocios"],["vacation","vacaciones"],["stay","quedarse"],["how long","cuánto tiempo"],["declare","declarar"]],"sentences":[["I am here on vacation","Estoy aquí de vacaciones"],["I will stay for two weeks","Me quedaré dos semanas"],["I have nothing to declare","No tengo nada que declarar"]],"dialogue":[["A","What's the purpose of your visit?","¿Cuál es el propósito de su visita?"],["B","Tourism.","Turismo."],["A","How long are you staying?","¿Cuánto tiempo se quedará?"],["B","Ten days.","Diez días."]],"tip":{"title":"Futuro con will","body":"Para decir lo que vas a hacer: «will» + verbo. Es igual para todas las personas.","examples":[["I will stay ten days","Me quedaré diez días"],["She will travel tomorrow","Ella viajará mañana"]]}},{"id":"m3u1-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3u2","title":"En el hotel","goal":"Haz el check-in, pide lo que necesitas y pregunta qué visitar.","color":"mango","lessons":[{"id":"m3u2-l1","title":"Llegar al hotel","words":[["room","habitación"],["key card","tarjeta de la habitación"],["floor","piso"],["breakfast","desayuno"],["wifi password","clave del wifi"],["check out","salida del hotel"]],"sentences":[["Is breakfast included?","¿El desayuno está incluido?"],["What is the wifi password?","¿Cuál es la clave del wifi?"],["Your room is on the fifth floor","Su habitación está en el quinto piso"]],"dialogue":[["A","Welcome! Do you have a reservation?","¡Bienvenido! ¿Tiene reserva?"],["B","Yes, under the name Gómez.","Sí, a nombre de Gómez."],["A","Here is your key card.","Aquí está la tarjeta de su habitación."],["B","Thank you. What time is check out?","Gracias. ¿A qué hora es la salida?"]]},{"id":"m3u2-l2","title":"Pedir cosas","words":[["towel","toalla"],["pillow","almohada"],["air conditioning","aire acondicionado"],["noisy","ruidoso"],["clean","limpiar"],["extra","adicional"]],"sentences":[["Could I have an extra towel?","¿Me podría dar una toalla adicional?"],["The air conditioning doesn't work","El aire acondicionado no funciona"],["The room is very noisy","La habitación es muy ruidosa"]],"dialogue":[["B","Hello, this is room 305.","Hola, habla la habitación 305."],["A","How can I help you?","¿En qué le puedo ayudar?"],["B","We need another pillow, please.","Necesitamos otra almohada, por favor."],["A","Sure, right away.","Claro, enseguida."]],"tip":{"title":"Could I…?","body":"«Could I have…?» es la forma más amable de pedir algo en un hotel o tienda.","examples":[["Could I have a towel?","¿Me podría dar una toalla?"],["Could you clean the room?","¿Podría limpiar la habitación?"]]}},{"id":"m3u2-l3","title":"¿Qué visitar?","words":[["recommend","recomendar"],["nearby","cerca"],["museum","museo"],["beach","playa"],["tour","recorrido"],["worth it","vale la pena"]],"sentences":[["Can you recommend a restaurant nearby?","¿Me recomienda un restaurante cerca?"],["Is the museum worth it?","¿Vale la pena el museo?"],["The tour starts at ten","El recorrido empieza a las diez"]],"dialogue":[["B","What can we visit today?","¿Qué podemos visitar hoy?"],["A","The old town is beautiful.","El centro histórico es hermoso."],["B","Is it far?","¿Queda lejos?"],["A","No, it's a ten minute walk.","No, queda a diez minutos caminando."]]},{"id":"m3u2-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3u3","title":"Direcciones y transporte","goal":"Pregunta cómo llegar y muévete en taxi, metro y bus.","color":"mint","lessons":[{"id":"m3u3-l1","title":"¿Cómo llego?","words":[["how do I get to","cómo llego a"],["block","cuadra"],["across from","al frente de"],["far","lejos"],["map","mapa"],["downtown","el centro"]],"sentences":[["How do I get to the station?","¿Cómo llego a la estación?"],["It's two blocks from here","Queda a dos cuadras de aquí"],["Is it far from here?","¿Queda lejos de aquí?"]],"dialogue":[["B","Excuse me, how do I get to the museum?","Disculpe, ¿cómo llego al museo?"],["A","Go straight two blocks.","Siga derecho dos cuadras."],["B","And then?","¿Y después?"],["A","Turn right. It's across from the bank.","Gire a la derecha. Queda al frente del banco."]]},{"id":"m3u3-l2","title":"Taxi y aplicaciones","words":[["ride","carrera"],["driver","conductor"],["fare","tarifa"],["stop here","pare aquí"],["airport","aeropuerto"],["traffic","tráfico"]],"sentences":[["To the airport, please","Al aeropuerto, por favor"],["How much is the fare?","¿Cuánto es la tarifa?"],["You can stop here","Puede parar aquí"]],"dialogue":[["A","Where to?","¿A dónde va?"],["B","Downtown, please. How long does it take?","Al centro, por favor. ¿Cuánto se demora?"],["A","About twenty minutes with traffic.","Unos veinte minutos con tráfico."],["B","Perfect, thanks.","Perfecto, gracias."]]},{"id":"m3u3-l3","title":"Metro y bus","words":[["ticket","tiquete"],["stop","parada"],["line","línea"],["transfer","transbordo"],["next","siguiente"],["get off","bajarse"]],"sentences":[["Which line goes downtown?","¿Qué línea va al centro?"],["I need to get off at the next stop","Me tengo que bajar en la siguiente parada"],["A ticket to the center, please","Un tiquete al centro, por favor"]],"dialogue":[["B","Does this bus go to the beach?","¿Este bus va a la playa?"],["A","No, take line five.","No, tome la línea cinco."],["B","Where do I get off?","¿Dónde me bajo?"],["A","At the last stop.","En la última parada."]]},{"id":"m3u3-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3u4","title":"Entrevista de trabajo","goal":"Preséntate, responde preguntas difíciles y cierra bien la entrevista.","color":"rose","lessons":[{"id":"m3u4-l1","title":"Hablar de ti","words":[["experience","experiencia"],["skills","habilidades"],["strengths","fortalezas"],["team","equipo"],["responsible","responsable"],["hardworking","trabajador"]],"sentences":[["I have five years of experience","Tengo cinco años de experiencia"],["I like working in a team","Me gusta trabajar en equipo"],["I am responsible and hardworking","Soy responsable y trabajador"]],"dialogue":[["A","Tell me about yourself.","Cuénteme sobre usted."],["B","I'm a nurse with five years of experience.","Soy enfermera con cinco años de experiencia."],["A","Why do you want this job?","¿Por qué quiere este trabajo?"],["B","Because I want to grow professionally.","Porque quiero crecer profesionalmente."]]},{"id":"m3u4-l2","title":"Preguntas difíciles","words":[["weakness","debilidad"],["salary","salario"],["schedule","horario"],["available","disponible"],["goal","meta"],["improve","mejorar"]],"sentences":[["My goal is to improve my English","Mi meta es mejorar mi inglés"],["I am available to start next month","Estoy disponible para empezar el próximo mes"],["What is the schedule?","¿Cuál es el horario?"]],"dialogue":[["A","What is your biggest weakness?","¿Cuál es su mayor debilidad?"],["B","Sometimes I work too much.","A veces trabajo demasiado."],["A","When can you start?","¿Cuándo puede empezar?"],["B","Next Monday.","El próximo lunes."]]},{"id":"m3u4-l3","title":"Cerrar la entrevista","words":[["hire","contratar"],["contract","contrato"],["benefits","beneficios"],["full time","tiempo completo"],["part time","medio tiempo"],["contact","contactar"]],"sentences":[["Is it full time or part time?","¿Es de tiempo completo o medio tiempo?"],["When will you contact me?","¿Cuándo me van a contactar?"],["Thank you for your time","Gracias por su tiempo"]],"dialogue":[["A","Do you have any questions?","¿Tiene alguna pregunta?"],["B","Yes. What are the benefits?","Sí. ¿Cuáles son los beneficios?"],["A","Health insurance and paid vacation.","Seguro de salud y vacaciones pagadas."],["B","Great, thank you.","Excelente, gracias."]],"tip":{"title":"Siempre cierra agradeciendo","body":"Al final de una entrevista en inglés es normal hacer una pregunta y agradecer el tiempo.","examples":[["Thank you for your time","Gracias por su tiempo"],["I look forward to hearing from you","Quedo atento a su respuesta"]]}},{"id":"m3u4-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3u5","title":"En la oficina","goal":"Habla en reuniones, pide informes y escribe correos de trabajo.","color":"ultra","lessons":[{"id":"m3u5-l1","title":"El día en la oficina","words":[["meeting","reunión"],["deadline","fecha límite"],["report","informe"],["boss","jefe"],["coworker","compañero de trabajo"],["email","correo"]],"sentences":[["The meeting is at three","La reunión es a las tres"],["The deadline is Friday","La fecha límite es el viernes"],["I sent the report to my boss","Le envié el informe a mi jefe"]],"dialogue":[["A","Do you have a minute?","¿Tienes un minuto?"],["B","Sure, what's up?","Claro, ¿qué pasa?"],["A","Can you send me the report?","¿Me puedes enviar el informe?"],["B","Yes, I'll send it today.","Sí, te lo envío hoy."]]},{"id":"m3u5-l2","title":"En la reunión","words":[["agree","estar de acuerdo"],["disagree","no estar de acuerdo"],["idea","idea"],["suggest","sugerir"],["question","pregunta"],["point","punto"]],"sentences":[["I agree with you","Estoy de acuerdo contigo"],["I suggest a new plan","Sugiero un plan nuevo"],["Good point","Buen punto"]],"dialogue":[["A","What do you think?","¿Qué opinas?"],["B","I think it's a good idea.","Creo que es una buena idea."],["A","Any questions?","¿Alguna pregunta?"],["B","No, everything is clear.","No, todo está claro."]]},{"id":"m3u5-l3","title":"Correos de trabajo","words":[["attach","adjuntar"],["follow up","hacer seguimiento"],["confirm","confirmar"],["as soon as possible","lo antes posible"],["regards","saludos"],["request","solicitud"]],"sentences":[["Please find the file attached","Adjunto encontrarás el archivo"],["Can you confirm the meeting?","¿Puedes confirmar la reunión?"],["I need it as soon as possible","Lo necesito lo antes posible"]],"dialogue":[["A","Hi, I'm calling to follow up on my request.","Hola, llamo para hacer seguimiento a mi solicitud."],["B","Let me check.","Déjeme revisar."],["B","It's approved. You will get an email today.","Está aprobada. Le llegará un correo hoy."],["A","Perfect, thank you!","¡Perfecto, gracias!"]]},{"id":"m3u5-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3u6","title":"Atención al cliente","goal":"Atiende clientes, resuelve problemas y cierra ventas en inglés.","color":"mango","lessons":[{"id":"m3u6-l1","title":"Recibir al cliente","words":[["welcome","bienvenido"],["assist","atender"],["customer","cliente"],["wait","esperar"],["moment","momento"],["glad","contento"]],"sentences":[["Welcome to our store","Bienvenido a nuestra tienda"],["One moment, please","Un momento, por favor"],["I'm glad to help","Con gusto le ayudo"]],"dialogue":[["A","Good afternoon, how may I assist you?","Buenas tardes, ¿en qué le puedo atender?"],["B","I'm looking for this product.","Estoy buscando este producto."],["A","One moment, please. I will check.","Un momento, por favor. Voy a revisar."],["B","Thank you.","Gracias."]]},{"id":"m3u6-l2","title":"Resolver problemas","words":[["apologize","disculparse"],["solve","resolver"],["issue","inconveniente"],["replace","reemplazar"],["immediately","de inmediato"],["understand","entender"]],"sentences":[["I understand the problem","Entiendo el problema"],["We will replace it immediately","Lo reemplazaremos de inmediato"],["We apologize for the issue","Pedimos disculpas por el inconveniente"]],"dialogue":[["B","My order arrived broken.","Mi pedido llegó roto."],["A","I'm so sorry. I understand.","Lo siento mucho. Entiendo."],["B","What can you do?","¿Qué pueden hacer?"],["A","We will send a new one tomorrow.","Le enviaremos uno nuevo mañana."]]},{"id":"m3u6-l3","title":"Vender y cerrar","words":[["offer","oferta"],["best seller","el más vendido"],["quality","calidad"],["guarantee","garantía"],["delivery","entrega"],["today only","solo por hoy"]],"sentences":[["This is our best seller","Este es nuestro producto más vendido"],["It has a one year guarantee","Tiene un año de garantía"],["Delivery is free today","La entrega es gratis hoy"]],"dialogue":[["B","Which one do you recommend?","¿Cuál me recomienda?"],["A","This one. It's our best seller.","Este. Es el más vendido."],["B","Does it have a guarantee?","¿Tiene garantía?"],["A","Yes, one year.","Sí, un año."]]},{"id":"m3u6-repaso","title":"Repaso de la unidad","review":true}]},{"id":"m3final","title":"Examen final","goal":"Apruebas con 3 errores o menos y obtienes tu certificado del módulo.","color":"rose","lessons":[{"id":"m3-examen","title":"Examen del módulo 3","exam":true}]}]}$nivela$::jsonb)
