insert into public.course_content (course_slug, data) values ('reto-militar-hombres', $nivela${"id":"reto-militar-hombres","kind":"standard","certNote":"completando las 21 misiones de entrenamiento","units":[{"id":"s1","title":"Semana 1 · Recluta","goal":"Aprende la técnica y crea el hábito. Intensidad suave.","color":"olive","lessons":[{"id":"briefing","title":"Instrucciones de la misión","kind":"read","blocks":[{"type":"text","title":"Bienvenido al reto","body":["Durante 21 días vas a entrenar como en un campamento militar, pero desde tu casa y con objetos que ya tienes. Cada día tiene una misión de 20 a 35 minutos.","El reto sube de intensidad cada semana: Recluta, Soldado y Comando. Los días 7 y 14 son de recuperación, y el día 1 y el 21 haces una prueba para comparar tu avance."]},{"type":"checklist","title":"Tu equipo","items":["Una silla firme (sin ruedas), apoyada contra la pared","Dos botellas de agua llenas de 1 a 1,5 litros","Una mochila con 3 o 4 libros","Una toalla o tapete","Una botella de agua para hidratarte","Ropa cómoda y tenis"]},{"type":"note","tone":"safety","title":"Antes de empezar","body":"Si tienes una condición médica, una lesión, estás embarazada o llevas mucho tiempo sin hacer ejercicio, consulta a tu médico antes de iniciar. Si sientes dolor agudo, mareo o falta de aire fuera de lo normal, detente."},{"type":"text","title":"Cómo funciona cada día","body":["Calentamiento de 3 ejercicios, después el circuito: haces cada ejercicio seguido, descansas al final y repites las rondas indicadas.","Esta versión usa flexiones completas, fondos y burpees desde el principio. Si un ejercicio te queda muy difícil, haz la versión más fácil que se indica."]}],"quiz":[{"q":"Si sientes un dolor agudo o mareo, ¿qué haces?","options":["Paro y descanso; si sigue, consulto al médico","Sigo hasta terminar la ronda","Lo hago más rápido para acabar"],"answer":"Paro y descanso; si sigue, consulto al médico","explain":"Cansancio es normal; dolor agudo o mareo son señales para detenerse."},{"q":"¿Por qué se calienta antes de entrenar?","options":["Prepara músculos y articulaciones y reduce lesiones","Para cansarse antes","No es necesario"],"answer":"Prepara músculos y articulaciones y reduce lesiones","explain":"Cinco minutos de calentamiento suben la temperatura del cuerpo y lo preparan."}]},{"id":"dia-1","title":"Día 1 · Prueba inicial y cuerpo completo","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 1","body":["Hoy trabajamos todo el cuerpo. Es la base de un buen soldado: fuerza en piernas, pecho, espalda y abdomen."]},{"type":"checklist","title":"Prueba inicial: anota tus resultados","items":["Flexiones seguidas en 1 minuto","Sentadillas en 1 minuto","Segundos que aguantas la plancha","Saltos de tijera en 1 minuto"]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Cuerpo completo","rounds":3,"rest":60,"items":[{"ex":"sentadilla","amount":"15 repeticiones"},{"ex":"flexion","amount":"10 repeticiones"},{"ex":"remoMochila","amount":"12 repeticiones"},{"ex":"plancha","amount":"30 segundos"},{"ex":"tijera","amount":"30 repeticiones"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Hidratación","body":"Toma agua antes, durante y después de entrenar. Ten una botella cerca durante el circuito."}],"quiz":[{"q":"En la plancha, ¿cómo debe estar la cadera?","options":["Alineada con hombros y talones","Bien arriba, en forma de V","Caída hacia el piso"],"answer":"Alineada con hombros y talones","explain":"El cuerpo debe formar una línea recta, con abdomen y glúteos apretados."},{"q":"¿Qué silla sirve para los fondos?","options":["Una silla firme apoyada contra la pared","Una silla con ruedas","Cualquier silla plegable"],"answer":"Una silla firme apoyada contra la pared","explain":"La silla no se puede mover: tu peso va sobre ella."}]},{"id":"dia-2","title":"Día 2 · Piernas y glúteos","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 2","body":["Piernas fuertes para marchar lejos. Hoy la misión es tren inferior: controla cada repetición."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Piernas y glúteos","rounds":3,"rest":60,"items":[{"ex":"zancada","amount":"10 por pierna"},{"ex":"sentadilla","amount":"20 repeticiones"},{"ex":"puente","amount":"15 repeticiones"},{"ex":"talones","amount":"20 repeticiones"},{"ex":"pared","amount":"30 segundos"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Sueño","body":"Dormir entre 7 y 9 horas es cuando tu cuerpo repara el músculo. El descanso también es entrenamiento."}],"quiz":[{"q":"¿Cuándo se exhala en una flexión?","options":["Al subir, en el esfuerzo","Al bajar","Se aguanta la respiración"],"answer":"Al subir, en el esfuerzo","explain":"Exhalar en el esfuerzo te da más estabilidad y evita marearte."},{"q":"En la zancada, la rodilla de adelante…","options":["No pasa mucho la punta del pie","Va lo más adelante posible","Se gira hacia adentro"],"answer":"No pasa mucho la punta del pie","explain":"Así repartes el peso entre cadera y rodilla y la proteges."}]},{"id":"dia-3","title":"Día 3 · Pecho, hombros y brazos","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 3","body":["Brazos y hombros listos para cargar el equipo. Usa botellas y la mochila como tu armamento."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Pecho, hombros y brazos","rounds":3,"rest":60,"items":[{"ex":"flexion","amount":"12 repeticiones"},{"ex":"fondos","amount":"12 repeticiones"},{"ex":"pressBotellas","amount":"15 repeticiones"},{"ex":"remoMochila","amount":"15 repeticiones"},{"ex":"plancha","amount":"30 segundos"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Comida real","body":"Llena la mitad del plato con verduras, una porción de proteína (huevo, pollo, fríjol, pescado) y una de carbohidrato."}],"quiz":[{"q":"Si sientes un dolor agudo o mareo, ¿qué haces?","options":["Paro y descanso; si sigue, consulto al médico","Sigo hasta terminar la ronda","Lo hago más rápido para acabar"],"answer":"Paro y descanso; si sigue, consulto al médico","explain":"Cansancio es normal; dolor agudo o mareo son señales para detenerse."},{"q":"¿Para qué sirve el día de recuperación?","options":["Para que el músculo se repare y se fortalezca","Para perder el ritmo","No sirve para nada"],"answer":"Para que el músculo se repare y se fortalezca","explain":"El músculo se fortalece mientras descansa, no solo mientras entrenas."}]},{"id":"dia-4","title":"Día 4 · Abdomen y cardio","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 4","body":["Un abdomen firme protege tu espalda. Hoy combinamos core y cardio para quemar energía."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Abdomen y cardio","rounds":3,"rest":60,"items":[{"ex":"abdominal","amount":"15 repeticiones"},{"ex":"escalador","amount":"20 repeticiones"},{"ex":"plancha","amount":"40 segundos"},{"ex":"rodillasArriba","amount":"30 segundos"},{"ex":"tijera","amount":"30 repeticiones"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Constancia","body":"Vale más entrenar 20 minutos todos los días que 2 horas una vez a la semana."}],"quiz":[{"q":"¿Qué silla sirve para los fondos?","options":["Una silla firme apoyada contra la pared","Una silla con ruedas","Cualquier silla plegable"],"answer":"Una silla firme apoyada contra la pared","explain":"La silla no se puede mover: tu peso va sobre ella."},{"q":"¿Por qué se calienta antes de entrenar?","options":["Prepara músculos y articulaciones y reduce lesiones","Para cansarse antes","No es necesario"],"answer":"Prepara músculos y articulaciones y reduce lesiones","explain":"Cinco minutos de calentamiento suben la temperatura del cuerpo y lo preparan."}]},{"id":"dia-5","title":"Día 5 · Circuito de combate","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 5","body":["Circuito largo y continuo. Mantén el ritmo y no te detengas más de lo indicado."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Circuito de combate","rounds":3,"rest":60,"items":[{"ex":"burpee","amount":"8 repeticiones"},{"ex":"sentadilla","amount":"15 repeticiones"},{"ex":"flexion","amount":"10 repeticiones"},{"ex":"zancada","amount":"8 por pierna"},{"ex":"escalador","amount":"20 repeticiones"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Postura","body":"Si la técnica se daña por cansancio, haz menos repeticiones bien hechas. La calidad gana."}],"quiz":[{"q":"En la zancada, la rodilla de adelante…","options":["No pasa mucho la punta del pie","Va lo más adelante posible","Se gira hacia adentro"],"answer":"No pasa mucho la punta del pie","explain":"Así repartes el peso entre cadera y rodilla y la proteges."},{"q":"¿Cómo levantas la mochila en el remo?","options":["Espalda recta, llevando los codos hacia atrás","Con la espalda curvada","Jalando con el cuello"],"answer":"Espalda recta, llevando los codos hacia atrás","explain":"La fuerza sale de la espalda y los brazos, nunca de la espalda baja curvada."}]},{"id":"dia-6","title":"Día 6 · Intervalos de alta intensidad","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 6","body":["Trabajo corto e intenso. Da todo en cada intervalo y respira en los descansos."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","amount":"10 repeticiones"}]},{"type":"workout","title":"Circuito: Intervalos de alta intensidad","rounds":3,"rest":60,"items":[{"ex":"rodillasArriba","amount":"30 segundos"},{"ex":"burpee","amount":"6 repeticiones"},{"ex":"tijera","amount":"40 segundos"},{"ex":"escalador","amount":"30 segundos"}]},{"type":"text","title":"Enfriamiento","body":["Camina 2 minutos por la casa respirando profundo. Después estira piernas, pecho y espalda, 20 segundos cada uno."]},{"type":"note","tone":"tip","title":"Bebidas","body":"Cambia gaseosas y jugos de caja por agua. Es de los cambios que más se notan."}],"quiz":[{"q":"¿Para qué sirve el día de recuperación?","options":["Para que el músculo se repare y se fortalezca","Para perder el ritmo","No sirve para nada"],"answer":"Para que el músculo se repare y se fortalezca","explain":"El músculo se fortalece mientras descansa, no solo mientras entrenas."},{"q":"Si una repetición te sale con mala técnica por cansancio…","options":["Hago menos repeticiones, pero bien hechas","Sigo igual para cumplir el número","Lo hago más rápido"],"answer":"Hago menos repeticiones, pero bien hechas","explain":"La técnica correcta es lo que da resultados y evita lesiones."}]},{"id":"dia-7","title":"Día 7 · Recuperación activa","kind":"read","blocks":[{"type":"text","title":"Misión: recuperar","body":["Hoy no hay circuito. Camina de 20 a 30 minutos a paso rápido y luego estira con calma.","Revisa tu semana: ¿qué ejercicio te costó más? Mañana subimos de nivel."]},{"type":"checklist","title":"Estiramientos (30 segundos cada uno)","items":["Cuádriceps: de pie, lleva el talón al glúteo","Isquiotibiales: pierna estirada en la silla, inclínate adelante","Pecho: mano en el marco de la puerta, gira el cuerpo","Espalda: de rodillas, estira los brazos adelante en el piso","Hombros: cruza un brazo frente al pecho"]},{"type":"note","tone":"tip","title":"Descansar también es entrenar","body":"El músculo se fortalece mientras descansa. Duerme bien esta noche."}],"quiz":[{"q":"¿Para qué sirve el día de recuperación?","options":["Para que el músculo se repare y se fortalezca","Para perder el ritmo","No sirve para nada"],"answer":"Para que el músculo se repare y se fortalezca","explain":"El músculo se fortalece mientras descansa, no solo mientras entrenas."}]}]},{"id":"s2","title":"Semana 2 · Soldado","goal":"Más rondas y menos descanso. Tu cuerpo ya se está adaptando.","color":"sand","lessons":[{"id":"dia-8","title":"Día 8 · Cuerpo completo","kind":"read","workout":true,"blocks":[{"type":"text","title":"Misión del día 8","body":["Hoy trabajamos todo el cuerpo. Es la base de un buen soldado: fuerza en piernas, pecho, espalda y abdomen."]},{"type":"workout","title":"Calentamiento","rounds":1,"rest":0,"items":[{"ex":"rodillasArriba","amount":"60 segundos"},{"ex":"tijera","amount":"20 repeticiones"},{"ex":"sentadilla","